use boundedstack::BoundedStack;

#[test]
fn test_push_pop() {
    let mut s: BoundedStack<i32> = BoundedStack::new(3);
    assert!(s.push(1).is_ok());
    assert!(s.push(2).is_ok());
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None);
}

#[test]
fn test_capacity_exceeded() {
    let mut s: BoundedStack<&str> = BoundedStack::new(2);
    s.push("a").unwrap();
    s.push("b").unwrap();
    assert!(s.push("c").is_err());
}

#[test]
fn test_peek() {
    let mut s: BoundedStack<u32> = BoundedStack::new(5);
    assert_eq!(s.peek(), None);
    s.push(42).unwrap();
    assert_eq!(s.peek(), Some(&42));
    assert_eq!(s.len(), 1);  // peek doesn't remove
}

#[test]
fn test_is_empty_is_full() {
    let mut s: BoundedStack<i32> = BoundedStack::new(2);
    assert!(s.is_empty());
    assert!(!s.is_full());
    s.push(1).unwrap();
    s.push(2).unwrap();
    assert!(s.is_full());
    assert!(!s.is_empty());
}

#[test]
fn test_len() {
    let mut s: BoundedStack<i32> = BoundedStack::new(10);
    assert_eq!(s.len(), 0);
    s.push(1).unwrap();
    s.push(2).unwrap();
    assert_eq!(s.len(), 2);
    s.pop();
    assert_eq!(s.len(), 1);
}

